1	const priceList: Record<string, number> = {
2	  sword: 100,
3	  amulet: 60,
4	  staff: 80,
5	  potion: 40,
6	  rune: 25,
7	  moonstone: 25,
8	};
9	
10	type Item = { type: string };
11	
12	const RUNE_BLOCK_SIZE = 3;
13	const RUNE_BLOCK_PRICE = 60;
14	
15	const COMPONENT_TYPES = ["rune", "moonstone"];
16	
17	const sumOfItemPrices = (items: Item[]): number =>
18	  items.reduce((sum, item) => sum + priceList[item.type], 0);
19	
20	export const basePremium = (items: Item[]): number => {
21	  const nonComponents = items.filter(
22	    (item) => !COMPONENT_TYPES.includes(item.type),
23	  );
24	  let total = sumOfItemPrices(nonComponents);
25	  for (const type of COMPONENT_TYPES) {
26	    const count = items.filter((item) => item.type === type).length;
27	    if (count === RUNE_BLOCK_SIZE) {
28	      total += RUNE_BLOCK_PRICE;
29	    } else {
30	      total += count * priceList[type];
31	    }
32	  }
33	  return total;
34	};
